import {
  BaseSheet,
  InsertColOperation,
  InsertRowOperation,
  Operation,
  RemoveColOperation,
  RemoveRowOperation,
  Sheet,
  UpdateCellOperation,
  InsertAnnotationOperation,
  DeleteAnnotationOperation,
} from '@bzl/sheet-js';
import { initialDoc } from '../utils';
import { SheetOTType } from '../../src';
import { describe, expect, beforeEach, test, afterEach } from 'vitest';

const examplesOp = [
  {
    type: 'insert-annotation',
    op: {
      type: 'insert-annotation',
      uuid: 'aC1kuoPvASf3unPRh6HWBe',
      at: {
        row: 4,
        col: 4,
      },
    } as InsertAnnotationOperation,
  },
  {
    type: 'insert-annotation',
    op: {
      type: 'delete-annotation',
      uuid: 'aC1kuoPvASf3unPRh6HWBe',
      at: {
        row: 4,
        col: 4,
      },
    } as DeleteAnnotationOperation,
  },
];

describe.each(examplesOp)('left side to $type right side to:', ({ op }) => {
  let doc1: Omit<BaseSheet, 'apply'>;
  let doc2: Omit<BaseSheet, 'apply'>;
  const op1: InsertAnnotationOperation | DeleteAnnotationOperation = op;
  let op2: Operation;

  beforeEach(() => {
    doc1 = initialDoc() as Sheet;
    doc2 = initialDoc() as Sheet;
  });

  afterEach(() => {
    const [op12, op21] = SheetOTType.xTransformMxN([op1], [op2], 'left');
    console.log('op12,', op12);
    console.log('op21,', op21);

    doc1 = SheetOTType.apply(SheetOTType.apply({} as BaseSheet, op1) as BaseSheet, op21);
    doc2 = SheetOTType.apply(SheetOTType.apply({} as BaseSheet, op2) as BaseSheet, op12);
    console.log('doc1,', JSON.stringify(doc1));
    console.log('doc2,', JSON.stringify(doc2));
    expect(doc1).toStrictEqual(doc2);
  });

  test('update-cell', () => {
    op2 = {
      type: 'update-cell',
      at: [op1.at.col, op1.at.row],
      newV: {
        value: 4,
      },
      oldV: {
        value: 2,
      },
      id: '1',
    } as UpdateCellOperation;
  });

  describe('insert-row', () => {
    test('at before', () => {
      op2 = {
        type: 'insert-row',
        at: op1.at.row - 3,
        count: 2,
        id: '1',
      } as InsertRowOperation;
    });
    test('at after', () => {
      op2 = {
        type: 'insert-row',
        at: op1.at.row + 1,
        count: 2,
        id: '1',
      } as InsertRowOperation;
    });
    test('at same', () => {
      op2 = {
        type: 'insert-row',
        at: op1.at.row,
        count: 2,
        id: '1',
      } as InsertRowOperation;
    });
  });

  describe('remove-row', () => {
    test.only('at before', () => {
      op2 = {
        type: 'remove-row',
        at: op1.at.row - 3,
        count: 2,
        id: '1',
      } as RemoveRowOperation;
    });
    test('at after', () => {
      op2 = {
        type: 'remove-row',
        at: op1.at.row + 1,
        count: 2,
        id: '1',
      } as RemoveRowOperation;
    });
    test('at same', () => {
      op2 = {
        type: 'remove-row',
        at: op1.at.row,
        count: 2,
        id: '1',
      } as RemoveRowOperation;
    });
  });

  describe('insert-col', () => {
    test('at before', () => {
      op2 = {
        type: 'insert-col',
        at: op1.at.col - 1,
        count: 2,
        id: '1',
      } as InsertColOperation;
    });
    test('at after', () => {
      op2 = {
        type: 'insert-col',
        at: op1.at.col + 1,
        count: 2,
        id: '1',
      } as InsertColOperation;
    });
    test('at same', () => {
      op2 = {
        type: 'insert-col',
        at: op1.at.col,
        count: 2,
        id: '1',
      } as InsertColOperation;
    });
  });

  describe('remove-col', () => {
    test('at before', () => {
      op2 = {
        type: 'remove-col',
        at: op1.at.col - 1,
        count: 2,
        id: '1',
      } as RemoveColOperation;
    });
    test('at after', () => {
      op2 = {
        type: 'remove-col',
        at: op1.at.col + 1,
        count: 2,
        id: '1',
      } as RemoveColOperation;
    });
    test('at same', () => {
      op2 = {
        type: 'remove-col',
        at: op1.at.col,
        count: 2,
        id: '1',
      } as RemoveColOperation;
    });
  });
});
